"lenses": [
    {
      "title": "Sociology and systems",
      "body": "Look at institutions, relationships and shared expectations. Which rules or workplace habits shape who can participate and who has influence?"
    },
    {
      "title": "Psychology and implicit bias",
      "body": "Consider perception, learning and automatic associations. What evidence supports this decision, and where might an assumption need checking?"
    },
    {
      "title": "Economics and resources",
      "body": "Consider costs, available resources and tradeoffs. How might transportation, time, service availability or an unmet support need affect a person's options?"
    },
    {
      "title": "Cultural anthropology",
      "body": "Explore how meaning, history and everyday practices vary by context. What can we learn about the setting without assuming that it describes an individual?"
    },
    {
      "title": "Cross-cultural learning and communication",
      "body": "Consider language, communication, norms and values in context. Does a notice or meeting assume one language, communication style or way of making decisions? Ask each person what works for them and offer accessible choices."
    },
    {
      "title": "Ethnography and lived experience",
      "body": "Learn from careful observation, listening and people's own accounts. Who should shape the questions, and what consent and privacy protections are needed?"
    },
    {
      "title": "Humanities, social justice and equity",
      "body": "Examine stories, history, values and power. Whose experience is missing, and do policies or workplace practices create unequal barriers?"
    },
    {
      "title": "Workforce equity and culture of safety",
      "body": "Examine how hiring, development, workplace practices and access work across the team. Who can raise a concern, receive support and participate without being excluded?"
    },
    {
      "title": "Institutional culture and power",
      "body": "DHS and DSD have workplace habits, rules and decision-making power. When a process affects communities of color, people with disabilities or others with access needs, whose priorities shape it? Who can change the form, timeline, interpretation or meeting format, and how will people affected be heard?"
    }
  ]
